{ arg out=0, freq=440, amp=0.1, gate=1, atk=0.005, dec=0.3, sus=0.0, rel=0.1, bright=0.5;
    var sig, ampEnv;
    ampEnv = EnvGen.ar(
        Env.adsr(atk, dec, sus, rel, curve: -4),
        gate: gate,
        doneAction: 2
    );
    var baseCutoff = freq * 2 + (bright * 5000);
    var filterCutoff = baseCutoff * (0.5 + (ampEnv * 0.5));
    filterCutoff = filterCutoff.clip(50, 20000);
    sig = Saw.ar(freq);
    sig = LPF.ar(sig, filterCutoff, rq: 0.5);
    sig = sig * amp * ampEnv;
    Out.ar(out, sig ! 2);
}
